"""Deployment scripts: service files generated by install-service.sh (dry run), install.sh guards."""
import shutil
import subprocess

import pytest

from app.config import REPO_ROOT


@pytest.fixture
def app_copy(tmp_path):
    """A minimal app directory with a venv marker, so the scripts run without touching the real checkout."""
    root = tmp_path / "pdb-orchestrator"
    shutil.copytree(REPO_ROOT / "scripts", root / "scripts")
    shutil.copytree(REPO_ROOT / "deploy", root / "deploy")
    (root / "venv" / "bin").mkdir(parents=True)
    (root / "venv" / "bin" / "python").write_text("#!/bin/sh\n")
    (root / "venv" / "bin" / "python").chmod(0o755)
    return root


def dry_run(root, tmp_path, *args):
    env = {"PATH": "/usr/bin:/bin", "ENV_DIR": str(tmp_path / "etc"), "UNIT_DIR": str(tmp_path / "etc")}
    return subprocess.run([str(root / "scripts" / "install-service.sh"), "--dry-run", *args], env=env,
                          capture_output=True, text=True, timeout=60)


def test_service_files(app_copy, tmp_path):
    r = dry_run(app_copy, tmp_path, "--user", "nobody", "--host", "0.0.0.0", "--port", "8443")
    assert r.returncode == 0, r.stderr
    unit, env = r.stdout.split("### ")[1], r.stdout.split("### ")[2]
    assert f"WorkingDirectory={app_copy}/backend" in unit
    assert f"ExecStart={app_copy}/venv/bin/python -m app" in unit
    assert "User=nobody" in unit and "KillMode=mixed" in unit and "Restart=on-failure" in unit
    assert "ORCH_HOST=0.0.0.0" in env and "ORCH_PORT=8443" in env
    # a login shell that prints a message (nologin) must not end up in the values
    assert "not available" not in env
    assert "#ORACLE_SID=" in env and "\nPATH=/usr/local/bin:/usr/bin:/bin" in env
    if shutil.which("systemd-analyze"):
        (tmp_path / "u").mkdir()
        unit_file = tmp_path / "u" / "pdb-orchestrator.service"
        unit_file.write_text(unit.split("\n", 1)[1])
        (tmp_path / "etc").mkdir(exist_ok=True)
        (tmp_path / "etc" / "orchestrator.env").write_text(env.split("\n", 1)[1])
        v = subprocess.run(["systemd-analyze", "verify", str(unit_file)], capture_output=True, text=True)
        assert v.returncode == 0, v.stderr


@pytest.mark.parametrize("args,msg", [
    (["--user", "root"], "Refusing to run the service as root"),
    (["--user", "no-such-user-x"], "No such user"),
    (["--user", "nobody", "--port", "99999"], "Invalid port"),
    (["--user", "nobody", "--host", "evil;rm"], "Invalid host"),
])
def test_service_rejects_bad_input(app_copy, tmp_path, args, msg):
    r = dry_run(app_copy, tmp_path, *args)
    assert r.returncode == 2 and msg in r.stderr


def test_install_refuses_root():
    import os
    if os.geteuid() != 0:
        pytest.skip("only meaningful as root")
    r = subprocess.run([str(REPO_ROOT / "scripts" / "install.sh")], capture_output=True, text=True, timeout=30)
    assert r.returncode == 1 and "not as root" in r.stderr
